// P0 regression: saving an edited two-column PDF with bullet lists (Chromium/Skia producer)
// failed with "Text ... is missing after saving". Root causes:
//  1. PDFium's auto-generated ToUnicode for substituted fonts maps '-' to U+00AD (and ' ' to
//     U+00A0): the saved text really differed from what the user typed ("rain-sensor" -> "rain\xadsensor").
//  2. Layout merged runs from two columns into one "line", so validation reported untouched
//     text as missing.
//  3. List items were merged into one paragraph; a longer item pushed the following items down.
// Fixture: tests/fixtures/two_column_cv.pdf (synthetic, generated by Edge from fixtures/src).
#include "TestSupport.h"

#include "core/files/SafeFileWriter.h"
#include "core/persistence/Database.h"
#include "editor/pdf_native/PdfCanvas.h"
#include "editor/pdf_native/PdfEditSession.h"
#include "editor/pdf_native/PdfWorkspace.h"
#include "engines/pdf/PdfDocument.h"
#include "ui/widgets/CommonWidgets.h"

#include <QApplication>
#include <QDir>
#include <QFile>
#include <QRegularExpression>
#include <QScrollArea>
#include <QTemporaryDir>
#include <QTest>

#include <gtest/gtest.h>

using namespace folvio;
using namespace folvio::test;

namespace {

const QString kFixture = QStringLiteral(FOLVIO_FIXTURES "/two_column_cv.pdf");

QString compactText(QString s)
{
    s.remove(QRegularExpression(QStringLiteral("\\s+")));
    return s;
}

QString charBag(const QString& s)
{
    QString n = compactText(s);
    std::sort(n.begin(), n.end());
    return n;
}

QString copyFixture(const QTemporaryDir& dir, const QString& name = QStringLiteral("CV dwukolumnowe ąę.pdf"))
{
    const QString path = dir.filePath(name);
    QFile::copy(kFixture, path);
    QFile::setPermissions(path, QFile::ReadOwner | QFile::WriteOwner | QFile::ReadUser | QFile::WriteUser);
    return path;
}

int blockContaining(PdfEditSession& s, const QString& text, int page = 0)
{
    for (const TextBlock& b : s.blocks(page))
        if (s.blockState(page, b.id).text.contains(text))
            return b.id;
    return -1;
}

QRect widgetRect(const PdfDocument& doc, const QImage& img, const QRectF& pdfRect)
{
    return doc.pageToDevice(0, img.size()).mapRect(pdfRect).toAlignedRect();
}

} // namespace

TEST(RegressionP0, FixtureLayoutSeparatesColumnsAndListItems)
{
    ASSERT_TRUE(QFile::exists(kFixture));
    PdfEditSession s;
    ASSERT_EQ(s.open(kFixture), PdfEditSession::OpenStatus::Ok);
    for (const TextBlock& b : s.blocks(0)) {
        // No line may mix the left and right column (column gap is at x ~ 365..382).
        for (const TextLine& l : b.lines) {
            if (l.bounds.width() > 420)
                continue; // the introduction above the two-column grid spans the full width
            EXPECT_FALSE(l.bounds.left() < 360 && l.bounds.right() > 382) << l.text.toStdString();
        }
    }
    const int item1 = blockContaining(s, "Designed a greenhouse monitor");
    const int item2 = blockContaining(s, "Set up the irrigation schedule");
    ASSERT_GE(item1, 0);
    ASSERT_GE(item2, 0);
    EXPECT_NE(item1, item2) << "list items must be separate paragraphs";
    // Bullet marker glyphs are not part of the editable text.
    EXPECT_TRUE(s.blockState(0, item1).text.startsWith("Designed"));
    // A wrapped bold word stays in its paragraph.
    EXPECT_TRUE(s.blockState(0, blockContaining(s, "Przeprowadzi")).text.contains("Zima."));
}

TEST(RegressionP0, EditBulletParagraphSaveReopenEverythingElsePreserved)
{
    QTemporaryDir dir;
    const QString pdf = copyFixture(dir);
    const QByteArray originalHash = sha256OfFile(pdf);
    auto before = PdfDocument::openFile(pdf);
    ASSERT_TRUE(before);
    const QString beforeText = before->pageText(0);
    const QImage beforeImg = before->render(0, 2.0);
    QStringList beforeFonts;
    for (const PdfTextRun& r : before->textRuns(0))
        beforeFonts << r.fontName;
    beforeFonts.removeDuplicates();

    QRectF editedLine;
    QStringList otherLines;
    {
        PdfEditSession s;
        ASSERT_EQ(s.open(pdf), PdfEditSession::OpenStatus::Ok);
        const int id = blockContaining(s, "Designed a greenhouse monitor (~18k lines)");
        ASSERT_GE(id, 0);
        editedLine = s.blocks(0)[id].lines.first().bounds;
        for (const TextBlock& b : s.blocks(0))
            if (b.id != id)
                for (const TextLine& l : b.lines)
                    otherLines << l.text;
        EditOp op;
        op.page = 0;
        op.blockId = id;
        op.text = s.blockState(0, id).text.replace(" (~18k lines)", "");
        QString err;
        ASSERT_TRUE(s.apply(op, &err)) << err.toStdString();
        PdfEditSession::SaveOptions o;
        o.backupDir = dir.filePath("backups");
        const auto r = s.save(o);
        ASSERT_TRUE(r.ok) << r.error.toStdString();
        EXPECT_EQ(sha256OfFile(r.backupPath), originalHash);
    }

    auto after = PdfDocument::openFile(pdf);
    ASSERT_TRUE(after);
    const QString text = after->pageText(0);
    // The edited text is exactly what was typed: a real hyphen, not a soft hyphen.
    EXPECT_TRUE(text.contains("Designed a greenhouse monitor as four parts (sensor core")) << text.toStdString();
    EXPECT_FALSE(text.contains(QChar(0x00AD)));
    EXPECT_FALSE(text.contains("~18k"));
    // Every other line of the page is still present, character for character.
    const QString compactAfter = compactText(text);
    for (const QString& l : otherLines)
        EXPECT_TRUE(compactAfter.contains(compactText(l))) << "lost: " << l.toStdString();
    QString expectedBag = charBag(beforeText);
    for (QChar c : compactText(QStringLiteral(" (~18k lines)")))
        expectedBag.remove(expectedBag.indexOf(c), 1);
    EXPECT_EQ(charBag(text), expectedBag);
    EXPECT_TRUE(text.contains(QString::fromUtf8("Technik ogrodnictwa")));
    EXPECT_TRUE(text.contains(QString::fromUtf8("Przeprowadziła serię 120 pomiarów")));
    // The edited line keeps the document's own embedded font: no font was added.
    QStringList afterFonts;
    for (const PdfTextRun& r : after->textRuns(0))
        afterFonts << r.fontName;
    afterFonts.removeDuplicates();
    for (const QString& f : afterFonts)
        EXPECT_TRUE(beforeFonts.contains(f)) << "unexpected font " << f.toStdString();
    // Nothing outside the edited line changed visually.
    const QImage afterImg = after->render(0, 2.0);
    const QRect ignore = widgetRect(*before, beforeImg, editedLine.adjusted(-2, -3, 2, 3));
    EXPECT_EQ(pixelDifference(beforeImg, afterImg, ignore), 0.0);
    EXPECT_GT(pixelDifference(beforeImg, afterImg), 0.0);
}

TEST(RegressionP0, EveryParagraphCanBeEditedWithoutSideEffects)
{
    PdfEditSession probe;
    ASSERT_EQ(probe.open(kFixture), PdfEditSession::OpenStatus::Ok);
    const QString originalText = probe.original()->pageText(0);
    const QImage originalImg = probe.original()->render(0, 1.5);
    int edited = 0;
    for (const TextBlock& b : probe.blocks(0)) {
        if (!b.editable)
            continue;
        PdfEditSession s;
        ASSERT_EQ(s.open(kFixture), PdfEditSession::OpenStatus::Ok);
        QStringList lines = s.blockState(0, b.id).text.split('\n');
        const int cut = lines[0].lastIndexOf(' ');
        if (cut <= 0)
            continue;
        const QString removed = lines[0].mid(cut);
        lines[0] = lines[0].left(cut);
        EditOp op;
        op.page = 0;
        op.blockId = b.id;
        op.text = lines.join('\n');
        QString err;
        ASSERT_TRUE(s.apply(op, &err)) << "block " << b.id << ": " << err.toStdString();
        QByteArray out;
        ASSERT_TRUE(s.serialize(&out, &err));
        ASSERT_TRUE(s.verifyOutput(out, &err)) << "block " << b.id << ": " << err.toStdString();
        auto doc = PdfDocument::openData(out);
        QString expectedBag = charBag(originalText);
        for (QChar c : compactText(removed))
            expectedBag.remove(expectedBag.indexOf(c), 1);
        EXPECT_EQ(charBag(doc->pageText(0)), expectedBag) << "block " << b.id;
        const QRect ignore = widgetRect(*probe.original(), originalImg, b.lines.first().bounds.adjusted(-2, -3, 2, 3));
        EXPECT_LT(pixelDifference(originalImg, doc->render(0, 1.5), ignore), 0.0002) << "block " << b.id;
        ++edited;
    }
    EXPECT_GE(edited, 15);
}

TEST(RegressionP0, GrowingIntoOccupiedSpaceIsRefusedAndChangesNothing)
{
    PdfEditSession s;
    ASSERT_EQ(s.open(kFixture), PdfEditSession::OpenStatus::Ok);
    const int id = blockContaining(s, "Designed a greenhouse monitor");
    ASSERT_GE(id, 0);
    EditOp op;
    op.page = 0;
    op.blockId = id;
    op.text = s.blockState(0, id).text + " This additional sentence is far too long to fit into the space that this "
                                         "bullet point occupies, so it would run into the next item of the list.";
    QString err;
    EXPECT_FALSE(s.apply(op, &err));
    EXPECT_TRUE(err.contains("overlap")) << err.toStdString();
    EXPECT_FALSE(s.isModified());
    EXPECT_EQ(s.current()->pageText(0), s.original()->pageText(0));
    EXPECT_EQ(pixelDifference(s.current()->render(0, 1.0), s.original()->render(0, 1.0)), 0.0);
}

TEST(RegressionP0, CharactersMissingFromEmbeddedFontUseSystemFontWithCorrectUnicode)
{
    QTemporaryDir dir;
    const QString pdf = copyFixture(dir, "greek.pdf");
    PdfEditSession s;
    ASSERT_EQ(s.open(pdf), PdfEditSession::OpenStatus::Ok);
    const int id = blockContaining(s, "Set up the irrigation schedule");
    ASSERT_GE(id, 0);
    EditOp op;
    op.page = 0;
    op.blockId = id;
    // 'Ψ' is not in the embedded subset; '-' must stay a real hyphen.
    op.text = s.blockState(0, id).text.replace("Set up the irrigation schedule", QString::fromUtf8("Ψ-test schedule"));
    QString err;
    ASSERT_TRUE(s.apply(op, &err)) << err.toStdString();
    EXPECT_FALSE(s.lastWarnings().isEmpty()); // tells the user a replacement font was used
    PdfEditSession::SaveOptions o;
    o.backupDir = dir.filePath("b");
    ASSERT_TRUE(s.save(o).ok);
    const QString text = pdfText(pdf);
    EXPECT_TRUE(text.contains(QString::fromUtf8("Ψ-test schedule"))) << text.toStdString();
    EXPECT_FALSE(text.contains(QChar(0x00AD)));
    // Independent reader: the ToUnicode map must give the same characters to other applications.
    if (havePython())
        EXPECT_TRUE(runPython("import sys, pypdf\n"
                              "t = pypdf.PdfReader(sys.argv[1]).pages[0].extract_text()\n"
                              "sys.exit(0 if '\\u03a8-test' in t and '\\u00ad' not in t else 1)\n",
                              {pdf}));
}

TEST(RegressionP0, ValidatorDetectsRealLossAndMissingEdits)
{
    PdfEditSession a;
    ASSERT_EQ(a.open(kFixture), PdfEditSession::OpenStatus::Ok);
    const int edited = blockContaining(a, "Set up the irrigation schedule");
    EditOp op;
    op.page = 0;
    op.blockId = edited;
    op.text = a.blockState(0, edited).text.replace("Set up", "Configured");
    ASSERT_TRUE(a.apply(op));
    QByteArray good;
    ASSERT_TRUE(a.serialize(&good, nullptr));
    QString err;
    EXPECT_TRUE(a.verifyOutput(good, &err)) << err.toStdString();

    // The original file lacks the edit -> must be rejected.
    EXPECT_FALSE(a.verifyOutput(a.original()->sourceData(), &err));
    // A file where another paragraph silently disappeared -> must be rejected.
    PdfEditSession b;
    ASSERT_EQ(b.open(kFixture), PdfEditSession::OpenStatus::Ok);
    EditOp lossy = op;
    ASSERT_TRUE(b.apply(lossy));
    EditOp del;
    del.page = 0;
    del.blockId = blockContaining(b, "Przeprowadzi");
    del.text.clear();
    ASSERT_TRUE(b.apply(del));
    QByteArray bad;
    ASSERT_TRUE(b.serialize(&bad, nullptr));
    EXPECT_FALSE(a.verifyOutput(bad, &err));
    EXPECT_TRUE(err.contains("missing")) << err.toStdString();
}

TEST(RegressionP0, UnreadableCharactersAreNeverWritten)
{
    PdfEditSession s;
    ASSERT_EQ(s.open(kFixture), PdfEditSession::OpenStatus::Ok);
    const int id = blockContaining(s, "Set up the irrigation schedule");
    EditOp op;
    op.page = 0;
    op.blockId = id;
    op.text = s.blockState(0, id).text.replace("Set up", QString(QChar(0xFFFD)) + " up");
    QString err;
    EXPECT_FALSE(s.apply(op, &err));
    EXPECT_FALSE(s.isModified());
}

TEST(RegressionP0, FailedVerificationKeepsOriginalAndEditsThenRetrySucceeds)
{
    QTemporaryDir dir;
    const QString pdf = copyFixture(dir, "retry.pdf");
    const QByteArray hash = sha256OfFile(pdf);
    PdfEditSession s;
    ASSERT_EQ(s.open(pdf), PdfEditSession::OpenStatus::Ok);
    const int id = blockContaining(s, "Set up the irrigation schedule");
    EditOp op;
    op.page = 0;
    op.blockId = id;
    op.text = s.blockState(0, id).text.replace("Set up", "Configured");
    ASSERT_TRUE(s.apply(op));
    PdfEditSession::SaveOptions o;
    o.backupDir = dir.filePath("backups");

    PdfEditSession::setVerificationFailureForTesting(true);
    const auto failed = s.save(o);
    PdfEditSession::setVerificationFailureForTesting(false);
    EXPECT_FALSE(failed.ok);
    EXPECT_EQ(failed.status, SafeFileWriter::Status::ValidationFailed);
    EXPECT_EQ(sha256OfFile(pdf), hash);                              // original untouched
    EXPECT_TRUE(s.isModified());                                     // edits kept
    EXPECT_TRUE(s.blockState(0, id).text.startsWith("Configured"));
    EXPECT_TRUE(QDir(dir.filePath("backups")).entryList(QDir::Files).isEmpty()); // nothing replaced, no backup needed
    EXPECT_TRUE(QDir(dir.path()).entryList({".~folvio-*"}, QDir::Files | QDir::Hidden).isEmpty());

    const auto ok = s.save(o);                                       // retry after the problem is gone
    ASSERT_TRUE(ok.ok) << ok.error.toStdString();
    EXPECT_EQ(sha256OfFile(ok.backupPath), hash);
    EXPECT_TRUE(pdfText(pdf).contains("Configured the irrigation schedule"));
}

// ---- Through the Qt user interface ---------------------------------------------------

namespace {

struct UiFixture {
    QTemporaryDir dir;
    QString pdf;
    PdfWorkspace ws;
    PdfCanvas* canvas = nullptr;

    UiFixture()
    {
        Database::instance().open();
        Database::instance().setSetting("save.confirmFirst", false);
        Database::instance().setSetting("backup.enabled", true);
        pdf = copyFixture(dir);
        ws.resize(1300, 900);
        ws.show();
        // Shortcuts (Ctrl+S) only reach an active window; X servers without a window manager
        // (Xvfb in CI) do not activate new windows on their own.
        ws.activateWindow();
        if (!QTest::qWaitForWindowActive(&ws, 3000))
            ADD_FAILURE() << "test window could not be activated";
        QString err;
        if (!ws.openFile(pdf, &err))
            ADD_FAILURE() << err.toStdString();
        QTest::qWait(300);
        canvas = ws.findChild<PdfCanvas*>();
    }

    void clickBlock(int blockId)
    {
        const QRectF r = canvas->pdfRectToWidget(0, ws.session()->blocks(0)[blockId].lines.first().bounds);
        if (auto* scroll = qobject_cast<QScrollArea*>(canvas->parentWidget()->parentWidget()))
            scroll->ensureVisible(int(r.center().x()), int(r.center().y()), 50, 120);
        QTest::qWait(50);
        QTest::mouseClick(canvas, Qt::LeftButton, Qt::NoModifier, r.center().toPoint());
        QTest::qWait(50);
    }

    InlineTextEditor* editor() const { return ws.findChild<InlineTextEditor*>(); }

    void typeLines(const QStringList& lines)
    {
        InlineTextEditor* e = editor();
        QTest::keyClick(e, Qt::Key_A, Qt::ControlModifier);
        for (int i = 0; i < lines.size(); ++i) {
            if (i > 0)
                QTest::keyClick(e, Qt::Key_Return);
            QTest::keyClicks(e, lines[i]);
        }
    }
};

} // namespace

TEST(RegressionP0, EditAndSaveThroughTheQtInterface)
{
    UiFixture ui;
    ASSERT_TRUE(ui.ws.hasDocument());
    ASSERT_NE(ui.canvas, nullptr);
    const int id = blockContaining(*ui.ws.session(), "Designed a greenhouse monitor");
    ASSERT_GE(id, 0);
    QStringList lines = ui.ws.session()->blockState(0, id).text.split('\n');
    lines[0].replace(" (~18k lines)", "");

    ui.clickBlock(id);
    ASSERT_TRUE(ui.editor()->isVisible()) << "clicking a paragraph must open the in-place editor";
    ui.typeLines(lines);
    QTest::keyClick(ui.editor(), Qt::Key_Return, Qt::ControlModifier); // commit
    QTest::qWait(100);
    EXPECT_FALSE(ui.editor()->isVisible());
    ASSERT_TRUE(ui.ws.isModified());

    QTest::keyClick(ui.canvas, Qt::Key_S, Qt::ControlModifier); // Ctrl+S
    QTest::qWait(200);
    EXPECT_FALSE(ui.ws.isModified()) << "save via Ctrl+S failed";

    const QString text = pdfText(ui.pdf);
    EXPECT_TRUE(text.contains("Designed a greenhouse monitor as four parts (sensor core")) << text.toStdString();
    EXPECT_TRUE(text.contains("Set up the irrigation schedule"));
    EXPECT_TRUE(text.contains(QString::fromUtf8("Przeprowadziła serię 120 pomiarów")));
    ui.ws.closeDocument();
}

TEST(RegressionP0, RefusedEditKeepsTheTypedTextInTheEditor)
{
    UiFixture ui;
    const QByteArray hash = sha256OfFile(ui.pdf);
    const int id = blockContaining(*ui.ws.session(), "Designed a greenhouse monitor");
    QStringList lines = ui.ws.session()->blockState(0, id).text.split('\n');
    lines.last() += " Plus a much longer addition that cannot fit and would overlap the following list item below.";
    ui.clickBlock(id);
    ASSERT_TRUE(ui.editor()->isVisible());
    ui.typeLines(lines);
    QTest::keyClick(ui.editor(), Qt::Key_Return, Qt::ControlModifier);
    QTest::qWait(100);
    EXPECT_TRUE(ui.editor()->isVisible()) << "the user's text must stay available after a refused edit";
    EXPECT_TRUE(ui.editor()->toPlainText().contains("Plus a much longer addition"));
    EXPECT_FALSE(ui.ws.isModified());
    auto* banner = ui.ws.findChild<Banner*>();
    ASSERT_NE(banner, nullptr);
    EXPECT_TRUE(banner->isVisible());
    QTest::keyClick(ui.editor(), Qt::Key_Escape);
    EXPECT_EQ(sha256OfFile(ui.pdf), hash);
    ui.ws.closeDocument();
}
